import{_ as l,a0 as r,w as p,s as o,ao as d,I as n,a1 as s,A as a,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"怎样用 Tar 和 OpenSSL 给文件和目录加密及解密 | LCTT x X-CMD","titleTemplate":false,"description":"怎样用 Tar 和 OpenSSL 给文件和目录加密及解密 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样用 Tar 和 OpenSSL 给文件和目录加密及解密 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样用 Tar 和 OpenSSL 给文件和目录加密及解密 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20160806 How to Encrypt and Decrypt Files and Directories Using Tar and OpenSSL","title":"怎样用 Tar 和 OpenSSL 给文件和目录加密及解密","tag":"201611","desc":""},"relativePath":"201611/20160806 How to Encrypt and Decrypt Files and Directories Using Tar and OpenSSL.md","filePath":"[post].md"}'),u={name:"201611/20160806 How to Encrypt and Decrypt Files and Directories Using Tar and OpenSSL.md"};function g(c,e,m,h,f,T){const i=r("Link");return p(),o("div",null,[e[14]||(e[14]=d('<h1 id="怎样用-tar-和-openssl-给文件和目录加密及解密" tabindex="-1">怎样用 Tar 和 OpenSSL 给文件和目录加密及解密 <a class="header-anchor" href="#怎样用-tar-和-openssl-给文件和目录加密及解密" aria-label="Permalink to “怎样用 Tar 和 OpenSSL 给文件和目录加密及解密”">​</a></h1><p>当你有重要的敏感数据的时候，给你的文件和目录额外加一层保护是至关重要的，特别是当你需要通过网络与他人传输数据的时候。</p><p>由于这个原因，我在寻找一个可疑在 Linux 上加密及解密文件和目录的实用程序，幸运的是我找到了一个用 tar（Linux 的一个压缩打包工具）和 OpenSSL 来解决的方案。借助这两个工具，你真的可以毫不费力地创建和加密 tar 归档文件。</p><p>在这篇文章中，我们将了解如何使用 OpenSSL 创建和加密 tar 或 gz（gzip，另一种压缩文件）归档文件：</p><p>牢记使用 OpenSSL 的常规方式是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openssl command command-options arguments</span></span></code></pre></div><h3 id="在-linux-中加密文件" tabindex="-1">在 Linux 中加密文件 <a class="header-anchor" href="#在-linux-中加密文件" aria-label="Permalink to “在 Linux 中加密文件”">​</a></h3><p>要加密当前工作目录的内容（根据文件的大小，这可能需要一点时间）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tar -czf - * | openssl enc -e -aes256 -out secured.tar.gz</span></span></code></pre></div><p>上述命令的解释：</p><ol><li><code>enc</code> - openssl 命令使用加密进行编码</li><li><code>-e</code> – 用来加密输入文件的 <code>enc</code> 命令选项，这里是指前一个 tar 命令的输出</li><li><code>-aes256</code> – 加密用的算法</li><li><code>-out</code> – 用于指定输出文件名的 <code>enc</code> 命令选项，这里文件名是 <code>secured.tar.gz</code></li></ol><h3 id="在-linux-中解密文件" tabindex="-1">在 Linux 中解密文件 <a class="header-anchor" href="#在-linux-中解密文件" aria-label="Permalink to “在 Linux 中解密文件”">​</a></h3><p>要解密上述 tar 归档内容，使用以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openssl enc -d -aes256 -in secured.tar.gz | tar xz -C test</span></span></code></pre></div><p>上述命令的解释：</p><ol><li><code>-d</code> – 用于解密文件</li><li><code>-C</code> – 提取内容到 <code>test</code> 子目录</li></ol><p>下图展示了加解密过程，以及当你尝试执行以下操作时会发生什么：</p><ol><li>以传统方式提取 tar 包的内容</li><li>使用了错误的密码的时候</li><li>当你输入正确的密码的时候</li></ol>',18)),n("p",null,[s(i,{href:"http://www.tecmint.com/wp-content/uploads/2016/08/Encrypt-Decrypt-Tar-Archive-Files-in-Linux.png"},{default:a(()=>[...e[0]||(e[0]=[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/08/Encrypt-Decrypt-Tar-Archive-Files-in-Linux.png",alt:"在 Linux 中加密和解密 Tar 归档文件"},null,-1)])]),_:1})]),e[15]||(e[15]=n("p",null,[n("em",null,"在 Linux 中加密和解密 Tar 归档文件")],-1)),e[16]||(e[16]=n("p",null,"当你在本地网络或因特网工作的时候，你可以随时通过加密来保护你和他人共享的重要文本或文件，这有助于降低将其暴露给恶意攻击者的风险。",-1)),e[17]||(e[17]=n("p",null,"我们研究了一种使用 OpenSSL（一个 openssl 命令行工具）加密 tar 包的简单技术，你可以参考它的手册页（man page）来获取更多信息和有用的命令。",-1)),e[18]||(e[18]=n("hr",null,null,-1)),n("p",null,[e[2]||(e[2]=t("via: ",-1)),s(i,{href:"http://www.tecmint.com/encrypt-decrypt-files-tar-openssl-linux/"},{default:a(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/encrypt-decrypt-files-tar-openssl-linux/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),s(i,{href:"http://www.tecmint.com/author/gacanepa/"},{default:a(()=>[...e[3]||(e[3]=[t("Gabriel Cánepa",-1)])]),_:1}),e[7]||(e[7]=t(" 译者：",-1)),s(i,{href:"https://github.com/OneNewLife"},{default:a(()=>[...e[4]||(e[4]=[t("OneNewLife",-1)])]),_:1}),e[8]||(e[8]=t(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:a(()=>[...e[10]||(e[10]=[t("Linux中国",-1)])]),_:1}),e[13]||(e[13]=t(" 荣誉推出",-1))])])}const k=l(u,[["render",g]]);export{S as __pageData,k as default};
